import{j as e}from"./index-Q5tmBBoz.js";import{I as t}from"./InfoPage-CouG5ON_.js";import"./PageHeader-D19aNveu.js";function a(){return e.jsx(t,{title:"Business partners",lead:"Brightwell works with companies, charities and governments of every size — on research, talent and shared social goals. This page explains the routes into partnership.",crumbs:[{to:"/",label:"Home"},{to:"/about",label:"About"},{label:"Business partners"}],sections:[{heading:"Why partner with Brightwell",body:["Partners tell us they choose Brightwell for three reasons: the depth of our research, the calibre of our students, and the honesty of our relationships. Agreements are co-designed, clearly documented and measured on outcomes.","We build long relationships rather than one-off contracts, and we are transparent about the interests and values that guide our decisions."],aside:{title:"Types of partnership",rows:[["Research collaboration","Joint labs and grants"],["Commercialisation","Licensing and spin-outs"],["Professional services","Campus and events"],["Procurement","Fair supply chain"]],links:[["/research","Research at Brightwell"]]}},{heading:"Talent and recruitment",body:["Employers join recruitment fairs, sponsor projects and offer internships to Brightwell students throughout the year. Our careers service helps with everything from the first poster to on-campus interviews.","Graduate employment is strong across finance, technology, the professions and the public sector, and companies return year after year for our students’ problem-solving approach."],list:{title:"Ways to engage",items:["University-wide and college careers fairs each term.","Sponsored student projects, hackathons and case competitions.","Internship and work placement programmes with academic credit.","Executive education short courses for your teams."]}},{heading:"Starting a conversation",body:["Tell us what you hope to achieve and we will introduce you to the right people — whether that is a research group, the commercialisation office or the careers service.","The partnerships team responds to initial enquiries within five working days and holds no obligation during early conversations."],aside:{title:"Talk to us",rows:[["Partnerships","partnerships@brightwell.ng"],["Commercialisation","venture@brightwell.ng"],["Procurement","suppliers@brightwell.ng"]],links:[["/contact","Contact us"]]}}]})}export{a as default};
